namespace Business.Abstractions.Domain.Quotes
{
    /// <summary>
    /// A priced insurance quote captured by an adviser. Persistence ignorant; mapped by Data.SQL configurations.
    /// </summary>
    public class Quote
    {
        // Internal key, never exposed over the API
        public Guid Id { get; set; }

        // Public identifier used in routes
        public Guid Identifier { get; set; }

        // Human readable reference (QT-000123), generated by the database
        public string Reference { get; set; } = string.Empty;

        public string AdviserId { get; set; } = string.Empty;

        public string ClientFullName { get; set; } = string.Empty;
        public DateOnly ClientDateOfBirth { get; set; }
        public bool ClientIsSmoker { get; set; }

        public string ProductCode { get; set; } = string.Empty;
        public decimal CoverAmount { get; set; }
        public int TermYears { get; set; }

        public decimal MonthlyPremium { get; set; }
        public string Currency { get; set; } = string.Empty;
        public string PricingVersion { get; set; } = string.Empty;

        // Snapshot of the rating factors used, so a stored premium stays explainable after pricing changes
        public Dictionary<string, decimal> RatingFactors { get; set; } = new();

        public QuoteStatus Status { get; set; }
        public string? Notes { get; set; }

        // Duplicate submission guards
        public string? IdempotencyKey { get; set; }
        public string RequestFingerprint { get; set; } = string.Empty;

        public DateTime CreatedAt { get; set; }
        public DateTime UpdatedAt { get; set; }

        // Optimistic concurrency token (Postgres xmin)
        public uint Version { get; set; }

        public List<QuoteStatusChange> StatusHistory { get; set; } = new();
    }
}
